select * from pilipili.statistics_info


        user_id = #{query.userId}


        and data_type = #{query.dataType}


        and statistics_date = #{query.statisticsDate}


         and  statistics_date >= #{query.statisticsDateStart}


         and  statistics_date <= #{query.statisticsDateEnd}



    order by ${query.orderBy}

select
ifnull(sum(statistics_count), 0) statisticsCount, data_type
from pilipili.statistics_info


        user_id = #{query.userId}


        and data_type = #{query.dataType}


        and statistics_date = #{query.statisticsDate}


         and  statistics_date >= #{query.statisticsDateStart}


         and  statistics_date <= #{query.statisticsDateEnd}


    group by data_type, statistics_date

select
ifnull(count(1), 0) statisticsCount, DATE_FORMAT(create_time, '%Y-%m-%d') statisticsDate
from pilipili.user


         and  DATE_FORMAT(create_time, '%Y-%m-%d') >= #{query.statisticsDateStart}


         and  DATE_FORMAT(create_time, '%Y-%m-%d') <= #{query.statisticsDateEnd}


group by statisticsDate
